import{_ as t,c as a,o as r,ag as i}from"./chunks/framework.CoPVQkzc.js";const s="/docs-website/assets/gs_web_browser_step_1.CFnx0zSQ.png",n="/docs-website/assets/gs_mcal_step_1.DRsgINn4.png",o="/docs-website/assets/gs_oie_credential_update_step_1.C6-6GfV3.png",l="/docs-website/assets/gs_oie_dashboard.DKWrQwvw.png",f=JSON.parse('{"title":"Accessing the Administrator","description":"Reaching a running OIE server, choosing between the web and desktop administrators, and logging in","frontmatter":{"title":"Accessing the Administrator","description":"Reaching a running OIE server, choosing between the web and desktop administrators, and logging in"},"headers":[],"relativePath":"engine/accessing_the_administrator.md","filePath":"engine/accessing_the_administrator.md","lastUpdated":1788476353000}'),c={name:"engine/accessing_the_administrator.md"};function h(d,e,p,g,u,m){return r(),a("div",null,e[0]||(e[0]=[i('<h1 id="accessing-the-administrator" tabindex="-1">Accessing the Administrator <a class="header-anchor" href="#accessing-the-administrator" aria-label="Permalink to &quot;Accessing the Administrator&quot;">​</a></h1><p>To verify that the OIE server is available, open a browser and enter the URL from the startup output, <code>https://&lt;host&gt;:8443/</code>. See <a href="./server_process_management.html">Server Process Management</a> if it is not up yet.</p><p>After accepting the self-signed certificate in your browser, you will see this page:</p><p><img src="'+s+'" alt="Open Integration Engine Server home Page indicating the service is available with launcher target url and button to explore the Client API"></p><p>From here there are two ways to administer the engine: a browser, or the desktop Administrator.</p><h2 id="web-administrator" tabindex="-1">Web Administrator <a class="header-anchor" href="#web-administrator" aria-label="Permalink to &quot;Web Administrator&quot;">​</a></h2><p><a href="https://github.com/gibson9583/oie-web-support-plugin" target="_blank" rel="noreferrer">Web Support</a> is a community extension by Chris Gibson that installs a browser-based administrator into the engine&#39;s own web server. It works read/write against the same REST API as the desktop client, covering channel editing, deployment, and the message browser. It requires OIE 4.6.0.</p><p>Install it as you would any other extension, described in the <a href="./plugins.html">plugin guide</a>, then restart the engine and open <code>https://&lt;host&gt;:8443/oie-webadmin/</code>. No launcher is involved. See <a href="./web_administrator.html">Web Administrator</a> for what it covers.</p><h2 id="desktop-administrator" tabindex="-1">Desktop Administrator <a class="header-anchor" href="#desktop-administrator" aria-label="Permalink to &quot;Desktop Administrator&quot;">​</a></h2><p>The desktop Administrator is a Java application and needs a launcher to start it. Copy the Administrator Launcher URL from the page above, then use one of the launchers below. See <a href="/docs-website/launchers/">Launchers</a> for the full list, and <a href="./desktop_administrator.html">Desktop Administrator</a> for a tour of the client.</p><h3 id="ballista" tabindex="-1">Ballista <a class="header-anchor" href="#ballista" aria-label="Permalink to &quot;Ballista&quot;">​</a></h3><p><a href="https://github.com/kayyagari/ballista/releases" target="_blank" rel="noreferrer">Ballista</a> is an open-source Administrator launcher for Open Integration Engine built on Tauri.</p><h3 id="launcher" tabindex="-1">Launcher <a class="header-anchor" href="#launcher" aria-label="Permalink to &quot;Launcher&quot;">​</a></h3><p><a href="https://github.com/diridium-com/launcher/releases" target="_blank" rel="noreferrer">Launcher</a> is a fork of Ballista, also built on Tauri and open source under MPL-2.0.</p><h3 id="mcal" tabindex="-1">MCAL <a class="header-anchor" href="#mcal" aria-label="Permalink to &quot;MCAL&quot;">​</a></h3><p>The original Mirth® Connect Administrator Launcher by NextGen Healthcare (MCAL) works with OIE. Here is how you can use it to launch the OIE Administrator client GUI application.</p><p>Open MCAL. If it&#39;s the first launch, the left panel with connections is empty.</p><p><img src="'+n+'" alt="MCAL application window showing &quot;no saved connections&quot; in left panel"></p><p>To work better with OIE, choose <code>Bundled Java 17</code></p><p>And just click on <code>Launch</code> at the top right screen.</p><p>You should see a progress bar that will load the files necessary to launch the Open Integration Engine client.</p><h2 id="logging-in" tabindex="-1">Logging in <a class="header-anchor" href="#logging-in" aria-label="Permalink to &quot;Logging in&quot;">​</a></h2><div class="info custom-block"><p class="custom-block-title">INFO</p><p>On 4.6.0 a new instance starts with:</p><ul><li>login: <strong>admin</strong></li><li>password: <strong>admin</strong></li></ul><p>A future release replaces this with a password generated on first boot.</p></div><p>Enter your credentials and click <code>Login</code> when the login screen appears. After a brief loading screen, you will see the OIE dashboard.</p><p>If this is your first login, you are prompted to change the default password.</p><p><img src="'+o+'" alt="Edit User screen requesting username, password, and optional demographic information"></p><p>Fill the information, and don&#39;t forget to set the <code>New Password</code> (2 times)</p><p>And click on <code>Finish</code></p><p><img src="'+l+'" alt="Application ready to use at the Dashboard screen showing no deployed channels and the server startup messages in the log section"></p><p>It&#39;s finished. Now you can start to use your OIE server.</p><div class="warning custom-block"><p class="custom-block-title">Every account is an administrator</p><p>All users are administrators by default, with privilege to write and execute channel scripts on the server. Grant access only to users who should be able to author and execute scripts, or install an RBAC plugin to create low-privileged roles.</p><p><a href="https://github.com/diridium-com/role-based-access-control" target="_blank" rel="noreferrer">Role Based Access Control</a> is a community extension that replaces the default authorization controller with roles and per-channel grants, and it works in both administrators.</p></div>',31)]))}const w=t(c,[["render",h]]);export{f as __pageData,w as default};
